const rows = items.map(i => i.json);
const today = new Date().toISOString().slice(0,10);
const yest = new Date(Date.now()-864e5).toISOString().slice(0,10);
const y = rows.filter(r => (r.Date||'').startsWith(yest));
const enq = y.filter(r => (r.Type||'').toLowerCase() !== 'sale');
const sales = y.filter(r => (r.Type||'').toLowerCase() === 'sale');
const rev = sales.reduce((s,r)=> s + (parseInt(String(r.Amount||'').replace(/\D/g,''))||0), 0);
const due = rows.filter(r => r.FollowUp && r.FollowUp <= today && r.Status !== 'Sold');
const bySrc = {};
enq.forEach(r => bySrc[r.Source||'Other'] = (bySrc[r.Source||'Other']||0)+1);
const text = `📊 ${$env.BRAND_NAME||'Showroom'} — daily digest\n\nYesterday: ${enq.length} enquiries (${Object.entries(bySrc).map(([k,v])=>k+': '+v).join(', ')||'none'})\nSales: ${sales.length} worth ₹${rev.toLocaleString('en-IN')}\n\n⏰ Follow-ups due today: ${due.length}\n${due.slice(0,8).map(r=>'• '+r.Customer+' ('+(r.Item||'')+') '+(r.Phone||'')).join('\n')}\n\n22K rate reminder: update in the Suite settings.`;
return [{ json: { text } }];
